ALTER TABLE "credit_accounts" ADD COLUMN "tester_topup_sequence" INTEGER NOT NULL DEFAULT 0;
CREATE TABLE "tester_entitlements" ("user_id" VARCHAR(64) PRIMARY KEY REFERENCES "users"("id") ON DELETE CASCADE,"enabled" BOOLEAN NOT NULL DEFAULT true,"revision" INTEGER NOT NULL DEFAULT 1,"reason" VARCHAR(500) NOT NULL,"granted_by_id" VARCHAR(64) NOT NULL,"expires_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "app_releases" ("id" VARCHAR(64) PRIMARY KEY,"label" VARCHAR(100) NOT NULL,"source_sha" VARCHAR(40) NOT NULL,"artifact_sha256" VARCHAR(64) NOT NULL,"manifest" JSONB NOT NULL,"public_notes" JSONB NOT NULL,"compatibility_version" INTEGER NOT NULL,"verified_at" TIMESTAMP(3) NOT NULL,"registered_by_id" VARCHAR(64) NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "app_release_channels" ("channel" VARCHAR(16) PRIMARY KEY,"release_id" VARCHAR(64) NOT NULL REFERENCES "app_releases"("id"),"revision" INTEGER NOT NULL DEFAULT 1,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "app_release_operations" ("id" VARCHAR(100) PRIMARY KEY,"request_hash" VARCHAR(64) NOT NULL,"action" VARCHAR(24) NOT NULL,"actor_id" VARCHAR(64) NOT NULL,"release_id" VARCHAR(64) NOT NULL,"previous_release_id" VARCHAR(64),"status" VARCHAR(24) NOT NULL,"result" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
